import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

test.describe("Upload vendor documents", () => {
  test("A file of exactly 10 MiB is accepted", { tag: "@DOC-05" }, async ({ apiAs }) => {
    // Background: signed in as member, a vendor in draft
    const member = await apiAs("member");
    const created = await member.post("/api/vendors", {
      data: {
        name: uniqueName("DOC-05 Vendor"),
        category: "software",
        contact_email: "vendor@example.com",
      },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = await created.json();
    expect(vendor.status).toBe("draft");

    // When I upload a text file of exactly 10 MiB as kind contract
    const buffer = Buffer.alloc(TEN_MIB, "x");
    expect(buffer.length).toBe(TEN_MIB);
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "contract",
        file: { name: "contract.txt", mimeType: "text/plain", buffer },
      },
      timeout: 120_000,
    });

    // Then the response status is 201
    expect(res.status(), await res.text()).toBe(201);
    const doc = await res.json();
    expect(doc.kind).toBe("contract");
    expect(doc.size_bytes).toBe(TEN_MIB);
  });
});
